<div id="notification-loading" hidden role="status" aria-live="polite" class="fixed inset-0 z-50 bg-white/70 p-6 backdrop-blur-[1px]"><span class="sr-only">Loading notifications</span><div class="mx-auto mt-28 max-w-5xl space-y-4 rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><div class="h-5 w-44 animate-pulse rounded bg-slate-200"></div>@for($i=0;$i<5;$i++)<div class="h-12 animate-pulse rounded-lg bg-slate-100"></div>@endfor</div></div>
<script>document.addEventListener('DOMContentLoaded',()=>{const rows=[...document.querySelectorAll('[data-notification-row]')],type=document.getElementById('notification-type-filter'),search=document.getElementById('notification-search'),empty=document.getElementById('notification-filter-empty'),count=document.getElementById('notification-count');const apply=()=>{let shown=0,q=(search?.value||'').toLowerCase().trim();rows.forEach(row=>{const match=(!type?.value||row.dataset.type===type.value.toLowerCase())&&(!q||(row.dataset.search||'').includes(q));row.hidden=!match;if(match)shown++});if(empty)empty.hidden=shown!==0;if(count)count.textContent=`Showing ${shown} of ${rows.length} notifications on this page`};type?.addEventListener('change',apply);search?.addEventListener('input',apply);apply();const loading=document.getElementById('notification-loading');document.getElementById('notification-filters')?.addEventListener('submit',()=>{if(loading)loading.hidden=false});document.querySelectorAll('nav[aria-label="Notification pages"] a').forEach(link=>link.addEventListener('click',()=>{if(link.getAttribute('aria-disabled')!=='true'&&loading)loading.hidden=false}));});</script>
